"""Freeze selected chemical contract and controls before interpreter implementation."""
import hashlib,json,shutil
from pathlib import Path
H=Path(__file__).resolve().parent;ROOT=H.parent;D=H/'NSC-002';E=H/'evaluation';E.mkdir(exist_ok=True)
def write(p,x):p.write_text(json.dumps(x,indent=2,ensure_ascii=False)+'\n',encoding='utf8')
comparison=json.loads((D/'candidate_scope_comparison.json').read_text(encoding='utf8'))
assert comparison['counts']['C']['FULL_NAME_APPLICABLE']==2
grammar='''(* ASCII case-insensitive, entire original source, no whitespace. *)
name       = group, { "-", group }, "benzene" ;
group      = locants, "-", [ multiplier ], substituent ;
locants    = locant, { ",", locant } ;
locant     = "1" | "2" | "3" | "4" | "5" | "6" ;
multiplier = "di" | "tri" ;
substituent= "bromo" | "chloro" | "fluoro" | "iodo" | "nitro" ;
(* Semantic guards: one to three groups, one to six distinct positions;
   one group per substituent type; multiplier count equals locant count;
   neutral, single-component substituted benzene, no other tokens. *)
'''
(D/'grammar.ebnf').write_text(grammar,encoding='utf8')
contract={'contract_id':'NSC-002','version':'1.0','chosen_candidate':'C','selection':'Compositional multiple locanted substitutions on benzene offer a reusable operation and two exact lexical opportunities, compared with zero for either frozen alternative.','scope':'One to three explicit halo/nitro groups and up to six distinct locants on a single neutral benzene; no suffixes or other operations.','partial_scope':'No partial-operation SUPPORT is claimed for a name that does not fully match. Unparsed surroundings may affect ownership and scope.','charge':'Nitro N+/O- is an internal resonance representation of a neutral substituent, not proof of a separately protonated ion; non-nitro charge remains unsupported.','identity':'NOT_ESTABLISHED','review':'CHEMICAL_REVIEW_PENDING','freeze_note':'The selected grammar is exactly provisional C, with its existing semantic guard that a substituent type appears in one group.'}
write(D/'selected_contract.json',contract)
rules={'rules':[{'id':'R1','name':'hydrogen replacement','authority':'https://iupac.qmul.ac.uk/BlueBook/P1.html#P-13.1','meaning':'Replace parent H by source-named substituent.'},{'id':'R2','name':'locant placement','authority':'https://iupac.qmul.ac.uk/BlueBook/P1.html#P-14.3','meaning':'Locants attach to immediately following prefix.'},{'id':'R3','name':'multiplicity','authority':'https://iupac.qmul.ac.uk/BlueBook/P1.html#P-14.2','meaning':'di/tri require corresponding number of locants.'},{'id':'R4','name':'benzene parent','authority':'https://iupac.qmul.ac.uk/BlueBook/P2.html','meaning':'Six equivalent ring positions; numbering is meaningful only relative to source pattern.'},{'id':'R5','name':'halo and nitro prefixes','authority':'https://iupac.qmul.ac.uk/BlueBook/P5.html','secondary':'https://old.goldbook.iupac.org/plain/N04158-plain.html','meaning':'Halo attaches via the element; nitro attaches via N, not O.'}]}
write(D/'nomenclature_rules.json',rules)
old=json.loads((ROOT/'nsc_architecture_experiment/NSC-001/semantic_constraint_schema_v2.json').read_text(encoding='utf8'));old['title']='NSC-002 interpretation using NSC-001 typed semantic interface';old['properties']['contract_id']={'const':'NSC-002'};old['properties']['contract_version']={'const':'1.0'}
write(D/'semantic_constraint_schema.json',old)
write(D/'semantic_constraint_extensions.json',{'reuse':'NSC-001 v2 SemanticInterpretation, SemanticValidation and source/operation/constraint types','change':'Contract identifier/version only; existing R1-R5 reference keys map to NSC-002 rule catalog.','dependency':'Multiple group operations and constraints may share parent claim; all spans and IDs must validate.','compatibility':'Existing NSC-001 schema and source are unchanged.'})
write(D/'chemical_review.json',{'status':'CHEMICAL_REVIEW_PENDING','qualified_human_reviewer':None,'authority':'IUPAC rules and independently documented example structures','notes':'Automated structure checks do not establish independent expert review. Public heldout is not blinded.'})
refs=['https://iupac.qmul.ac.uk/BlueBook/P1.html#P-13.1','https://iupac.qmul.ac.uk/BlueBook/P5.html']
def case(i,name,smiles,scope,result,why,reference,context=None):return {'id':i,'source_name':name,'candidate_structure':smiles,'contract_scope':scope,'source_claims':'source locants, multiplicity, substituent type and benzene parent' if scope=='IN_CONTRACT' else [],'expected_constraints':'parent ring substitution pattern' if scope=='IN_CONTRACT' else [],'expected_operation_result':result,'expected_dimension_result':'UNKNOWN','chemical_justification':why,'references':refs+[reference],'review_status':'CHEMICAL_REVIEW_PENDING','context':context or {}}
meta='https://pubchem.ncbi.nlm.nih.gov/compound/7928'; dib='https://pubchem.ncbi.nlm.nih.gov/compound/1_3-dibromobenzene'; nit='https://pubchem.ncbi.nlm.nih.gov/compound/6945'
dev=[case('D01','1-bromo-3-chlorobenzene','Brc1cccc(Cl)c1','IN_CONTRACT','SUPPORTED','Meta halo substituents at relative positions 1,3.',meta),case('D02','1-bromo-3-chlorobenzene','Brc1ccc(Cl)cc1','IN_CONTRACT','DIFFERENT','Para versus meta arrangement are constitutional isomers.',meta),case('D03','1,3-dibromobenzene','Brc1cccc(Br)c1','IN_CONTRACT','SUPPORTED','Two source-written locants with di multiplier.',dib),case('D04','1-chloro-2-nitrobenzene','Clc1ccccc1[N+](=O)[O-]','IN_CONTRACT','SUPPORTED','Nitro is N-attached and formal charge is internally balanced.',nit),case('D05','1-chloro-2-nitrobenzene','Clc1ccccc1N=O','IN_CONTRACT','UNKNOWN','Nitroso candidate is outside supported candidate graph and does not prove a specific contract contradiction.',nit),case('D06','1-bromo-3-chlorobenzene','Brc1cccc(Cl)c1 arbitrary','IN_CONTRACT','UNKNOWN','Invalid trailing text must fail strict parsing.',meta),case('D07','bromochlorobenzene','Brc1cccc(Cl)c1','OUT_OF_CONTRACT','OUT_OF_CONTRACT','Missing locants are unsupported, not necessarily chemically invalid.',meta),case('D08','1-bromo-3-chlorobenzene hydrochloride','Brc1cccc(Cl)c1.Cl','OUT_OF_CONTRACT','OUT_OF_CONTRACT','Unsupported surrounding salt words cannot supply a partial operation.',meta),case('D09','1-bromo-3-chlorobenzene','[13c]1(Br)cccc(Cl)c1','IN_CONTRACT','UNKNOWN','An isotope-labeled candidate exceeds source specificity.',meta),case('D10','1-bromo-3-chlorobenzene','ClC1=CC=CC(Br)=C1','IN_CONTRACT','SUPPORTED','Equivalent ring traversal and Kekule representation.',meta),case('D11','1-bromo-3-chlorobenzene','Brc1cccc(Cl)c1','IN_CONTRACT','UNKNOWN','Inadequate candidate correspondence prevents a decision.',meta,{'correspondence':'UNAVAILABLE'})]
held=[case('H01','1,2-dibromobenzene','Brc1ccccc1Br','IN_CONTRACT','SUPPORTED','Ortho dibromo pattern with two distinct locants.','https://pubchem.ncbi.nlm.nih.gov/compound/1_2-dibromobenzene'),case('H02','1,2-dibromobenzene','Brc1cccc(Br)c1','IN_CONTRACT','DIFFERENT','Meta and ortho substituent positions differ under all benzene symmetries.',dib),case('H03','1-chloro-2-nitrobenzene','Clc1ccccc1[N+]([O-])=O','IN_CONTRACT','SUPPORTED','Different nitro oxygen ordering is the same graph.',nit),case('H04','1,2-dibromobenzene','Brc1ccccc1Br.Cl','IN_CONTRACT','UNKNOWN','Additional component lies outside candidate comparison.',dib),case('H05','1,2-dibromobenzene-4-ol','Brc1ccccc1Br','OUT_OF_CONTRACT','OUT_OF_CONTRACT','Additional suffix is not interpreted.',dib)]
write(D/'development_controls.json',{'status':'FROZEN_REVIEW_PENDING','cases':dev});write(D/'heldout_controls.json',{'status':'PUBLIC_FROZEN_NOT_BLINDED','cases':held})
files=['provisional_candidate_scopes.json','provisional_scope_freeze.json','candidate_scope_comparison.json','grammar.ebnf','selected_contract.json','nomenclature_rules.json','semantic_constraint_schema.json','semantic_constraint_extensions.json','chemical_review.json','development_controls.json','heldout_controls.json']
